package workshop.vfx.paper.streams;

import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static workshop.vfx.paper.streams.StreamsFixture.*;
import workshop.vfx.delivery.*;
import workshop.vfx.math.core.*;
import workshop.vfx.paper.core.*;
import workshop.vfx.paper.m8.*;
import workshop.vfx.scene.*;

class DualStreamsTest {
    private static void vector(Vec3 expected,Vec3 actual){assertTrue(expected.sub(actual).length()<1e-12,()->expected+" != "+actual);}
    @Test void initialPairIsUpAndDown(){vector(Vec3.Y,StreamsEffect.directionA(0));vector(Vec3.Y.mul(-1),StreamsEffect.directionA(0).mul(-1));}
    @Test void cardinalPhasesAnd80TickPeriodAreExactToRoundoff(){for(int k=0;k<5;k++){var expected=new Vec3[]{Vec3.Y,Vec3.X.mul(-1),Vec3.Y.mul(-1),Vec3.X,Vec3.Y}[k];vector(expected,StreamsEffect.directionA(k*20));assertEquals(StreamsEffect.directionA(k*20),StreamsEffect.directionA(k*20+80));}}
    @Test void allPhasesAreUnitOpposedAndRotateInTheSameAngularDirection(){for(int age=0;age<200;age++){var a=StreamsEffect.directionA(age);assertEquals(1,a.length(),1e-15);assertEquals(0,a.z());var next=StreamsEffect.directionA(age+1);assertTrue(a.cross(next).z()>0);assertEquals(Vec3.ZERO,a.add(a.mul(-1)));}assertThrows(IllegalArgumentException.class,()->StreamsEffect.directionA(-1));}
    @Test void worldDirectionsFollowBodyYawAndIgnoreHeadAndCameraPitch(){for(float yaw:new float[]{0,45,90,180,270,-90,359.5f}){var f=new StreamsFixture();f.position.put(A,new double[]{7,70,-9,yaw,145,-90});f.normal();f.tick=120;var d=f.draft(A);var a=d.directions().get(DirectionalEmission.A).direction();double angle=Math.toRadians(yaw);vector(new Vec3(-Math.cos(angle),0,-Math.sin(angle)),a);vector(a.mul(-1),d.directions().get(DirectionalEmission.B).direction());f.position.get(A)[4]=-127;f.position.get(A)[5]=90;assertEquals(d.directions(),f.draft(A).directions());}}
    @Test void pairUsesOneRearTorsoOriginAndNoPlottedGeometry(){var f=new StreamsFixture();f.position.put(A,new double[]{7,70,-9,90,0,0});f.normal();var d=f.draft(A);var frame=frame(d);assertEquals(2,frame.pointCount());assertEquals(2,frame.batches().size());vector(new Vec3(8,71.55,-9),frame.batches().get(0).point(0));assertEquals(frame.batches().get(0).point(0),frame.batches().get(1).point(0));assertEquals(Set.of(QualityTier.SIMPLE),d.recipe().tiers());assertEquals(1,d.recipe().variant(QualityTier.SIMPLE).layers().get(0).shape().size());}
    @Test void allSpeedsHaveExactlyTwoDirectionalCallsPerStepAndNoPositionalFallback(){for(var speed:StreamSpeed.values()){var f=new StreamsFixture();f.start(speed);f.run();assertEquals(2,f.directional.size());assertTrue(f.sends.isEmpty());assertEquals(2,f.driver.lastReport().attemptedCalls());assertEquals(2,f.plan.reservedGeneratedPoints());for(var send:f.directional)assertEquals(speed.value(),send.motion().speed());f.account();}}
    @Test void cadenceHas50Steps100CallsAndNoLifetimeExtension(){var f=new StreamsFixture();f.tick=103;f.normal();long total=0;for(int age=0;age<200;age++){f.tick=103+age;f.run();assertEquals(age%4==0?2:0,f.directional.size());total+=f.directional.size();f.account();}assertEquals(100,total);assertEquals(50,f.plans);assertEquals(1,f.schedules);f.tick=303;f.run();assertFalse(f.registry.active());assertEquals(1,f.cancels);assertTrue(f.directional.isEmpty());}
    @Test void missedTicksDoNotPauseResetOrReplayPhase(){var f=new StreamsFixture();f.normal();var clock=f.draft(A).playback();f.tick=117;f.run();assertTrue(f.directional.isEmpty());f.tick=120;var d=f.draft(A);assertSame(clock,d.playback());assertEquals(20,d.frameOrdinal());vector(Vec3.X.mul(-1),d.directions().get(DirectionalEmission.A).direction());f.run();assertEquals(2,f.directional.size());assertEquals(1,f.plans);}
    @Test void invalidSpeedsAndDirectionsAreRejectedBeforeEmission(){for(double speed:new double[]{Double.NaN,Double.POSITIVE_INFINITY,-1,0,.09,.23})assertThrows(IllegalArgumentException.class,()->new DirectionalEmission(Vec3.Y,speed));for(var v:new Vec3[]{null,Vec3.ZERO,new Vec3(2,0,0),new Vec3(Double.NaN,0,0),new Vec3(Double.POSITIVE_INFINITY,0,0)})assertThrows(IllegalArgumentException.class,()->new DirectionalEmission(v,.15));}
    @Test void metadataIsImmutableAndLegacyConstructorsRetainEmptyPositionalPayloads(){var f=new StreamsFixture();f.normal();var d=f.draft(A);assertThrows(UnsupportedOperationException.class,()->d.directions().clear());var legacy=new EffectDraft(EffectKind.AURA,d.requestId(),d.owner(),d.ownerViewerId(),d.worldId(),d.anchor(),d.recipe(),d.tier(),d.playback(),d.now(),d.frameOrdinal());assertTrue(legacy.directions().isEmpty());var c=new RequestContext(d.requestId(),d.ownerViewerId(),d.worldId(),0,64,0,d.directions());assertThrows(UnsupportedOperationException.class,()->c.directions().clear());assertTrue(new RequestContext(0,0,0,0,0,0).directions().isEmpty());assertFalse(DraftIdentityGuard.accepts(new EffectDraft(EffectKind.STREAMS,d.requestId(),d.owner(),d.ownerViewerId(),d.worldId(),d.anchor(),d.recipe(),d.tier(),d.playback(),d.now(),0),f.ids,f.tick));}
    @Test void missingMetadataNeverFallsBackToStationaryEndRod(){var f=new StreamsFixture();f.normal();f.run();var d=f.draft(A);var c=new RequestContext(d.requestId(),d.ownerViewerId(),d.worldId(),0,64,0);long[] sent={0};var report=new DefaultPlanEmitter().emit(f.plan,Map.of(d.requestId(),c),f.health,(a,b)->Optional.empty(),(w,x,y,z)->Optional.empty(),(a,b,s,x,y,z)->sent[0]++,new EmissionLimits(10,10));assertEquals(0,sent[0]);assertEquals(2,report.placementsInSkippedDeliveries());assertEquals(1,report.skippedDeliveries().get(SkipReason.INVALID_DIRECTIONAL_CONTEXT));}
    @Test void unsupportedDirectionalSinkCountsFailuresWithoutCallingLegacySend(){var f=new StreamsFixture();f.normal();f.run();var d=f.draft(A);long[] positional={0};var c=new RequestContext(d.requestId(),d.ownerViewerId(),d.worldId(),0,64,0,d.directions());var report=new DefaultPlanEmitter().emit(f.plan,Map.of(d.requestId(),c),f.health,(a,b)->Optional.empty(),(w,x,y,z)->Optional.empty(),(a,b,s,x,y,z)->positional[0]++,new EmissionLimits(10,10));assertEquals(0,positional[0]);assertEquals(2,report.failedCalls());assertEquals(2,report.attemptedCalls());}
    @Test void onePointBudgetSkipsWholePairAndAccountsTheSelectedPlacement(){var f=new StreamsFixture(Map.of("maxCallsPerTick",1,"maxCallsPerViewerPerTick",1),Map.of());f.normal();f.run();assertEquals(1,f.plan.placements());assertTrue(f.directional.isEmpty());assertEquals(1,f.driver.lastReport().placementsInSkippedRecipients());assertTrue(f.driver.lastReport().skippedRecipients().containsKey(SkipReason.INCOMPLETE_STREAM_PAIR));f.account();}
    @Test void insufficientGenerationBudgetDoesNotEmitOrReservePartialPair(){var f=new StreamsFixture(Map.of("generatedPointBudget",1),Map.of());f.normal();f.run();assertEquals(0,f.plan.reservedGeneratedPoints());assertTrue(f.directional.isEmpty());assertEquals(Outcome.SKIPPED_GENERATION_BUDGET,f.plan.deliveries().getFirst().outcome());f.account();}
    @Test void oneSharedPlanAndTaskServeStreamsReferenceAndAura(){var f=new StreamsFixture(Map.of(),Map.of("maxEffectsPerPlayer",3));f.normal();f.reference.start(A,QualityTier.BALANCED,f.tick);f.auras.start(A,QualityTier.BALANCED,f.tick);f.run();assertEquals(1,f.plans);assertEquals(1,f.schedules);assertEquals(3,f.requests.size());assertEquals(2,f.directional.size());assertTrue(f.sends.size()>0);f.account();f.step();assertEquals(2,f.plans);assertTrue(f.directional.isEmpty());assertEquals(1,f.schedules);f.account();}
    @Test void recipientIsolationUsesExistingOwnerViewRangeAndWorldRules(){var f=new StreamsFixture();f.normal();f.run();assertEquals(2,f.directional.size());assertTrue(f.directional.stream().allMatch(s->s.viewer()==f.ids.viewerId(A)));f.canView.add(B);f.tick+=4;f.run();assertEquals(4,f.directional.size());f.position.get(B)[0]=33;f.tick+=4;f.run();assertEquals(2,f.directional.size());f.position.get(B)[0]=0;f.worlds.put(B,W2);f.tick+=4;f.run();assertEquals(2,f.directional.size());f.account();}
    @Test void permissionRevocationAfterPlanningSkipsAllAuthorizedPlacements(){var f=new StreamsFixture();f.normal();f.canView.add(B);f.afterPlan=()->{f.noUse.add(A);f.canView.clear();};f.run();assertTrue(f.directional.isEmpty());assertEquals(4,f.driver.lastReport().placementsInSkippedRecipients());f.account();}
    @Test void distinctOwnersHaveDistinctCurrentWorldDirectionsAndSpeeds(){var f=new StreamsFixture();f.position.get(B)[3]=90;f.normal();f.streams.start(B,StreamSpeed.SLOW,f.tick);f.canView.add(B);f.tick=120;f.run();assertEquals(6,f.directional.size());var as=f.directional.stream().filter(s->s.motion().speed()==.15).toList();var bs=f.directional.stream().filter(s->s.motion().speed()==.10).toList();assertEquals(4,as.size());assertEquals(2,bs.size());assertTrue(as.stream().anyMatch(s->s.motion().direction().x()<-.99));assertTrue(bs.stream().anyMatch(s->s.motion().direction().z()<-.99));f.account();}
    @Test void directionalFailuresAreBoundedAndDoNotDisableHistoricalEndRod(){var f=new StreamsFixture();f.normal();f.failDirection=true;for(int i=0;i<3;i++){f.tick=100+4*i;f.run();assertEquals(2,f.driver.lastReport().failedCalls());f.account();}assertTrue(f.health.isDisabled(DirectionalEmission.A));assertTrue(f.health.isDisabled(DirectionalEmission.B));assertFalse(f.health.isDisabled(DemoStyleCatalog.END_ROD));f.tick=112;f.run();assertEquals(0,f.driver.lastReport().attemptedCalls());f.account();}
    @Test void stopReplacementAndStaleCallbacksCannotRestartOrEmitOldParticles(){var f=new StreamsFixture();f.normal();var old=f.current();f.tick=104;f.start(StreamSpeed.FAST);assertTrue(old.finished(f.tick));assertEquals(1,f.registry.activeCount());assertEquals(1,f.schedules);var stale=f.callback;f.streams.stop(A);assertEquals(1,f.cancels);f.tick++;stale.run();assertEquals(0,f.plans);assertThrows(IllegalStateException.class,()->{f.driver.close();f.normal();});}
    @Test void deathDisconnectExpiryAndShutdownUseExistingCleanup(){for(int why=0;why<4;why++){var f=new StreamsFixture();f.normal();var effect=f.current();f.tick=101;if(why==0)f.dead.add(A);else if(why==1){f.offline.add(A);f.ids.release(A);}else if(why==2)f.tick=300;else f.driver.close();f.run();assertTrue(effect.finished(f.tick));assertFalse(f.registry.active());assertEquals(1,f.cancels);assertTrue(f.directional.isEmpty());}}
    @Test void teleportAndDimensionContinueFromFreshOriginAtCurrentPhase(){var f=new StreamsFixture();f.normal();var clock=f.draft(A).playback();f.tick=120;f.worlds.put(A,W2);f.position.put(A,new double[]{10000,80,-3000,90,45,-90});var d=f.draft(A);assertSame(clock,d.playback());assertEquals(20,d.frameOrdinal());f.run();assertTrue(f.directional.stream().allMatch(s->s.world()==f.ids.worldId(W2)));vector(new Vec3(10001,81.55,-3000),f.directional.getFirst().origin());vector(new Vec3(0,0,-1),d.directions().get(DirectionalEmission.A).direction());}
    @Test void invalidIdentityAndFailedStartDoNotRelaxExistingGuards(){var f=new StreamsFixture();f.normal();var old=f.current();f.tamper=s->null;assertThrows(IllegalArgumentException.class,()->f.start(StreamSpeed.SLOW));assertSame(old,f.current());f.tamper=s->replace(s,null,B,null,null,null,null,null,null,null,null,null);f.run();assertEquals(0,f.plans);assertFalse(f.registry.active());assertEquals(1,f.registry.rejections(AnchorRejection.OWNER_MISMATCH));}
    static final class Probe implements StreamsCommands.Endpoint{boolean use=true,player=true;int starts,stops;StreamSpeed speed;String reply="";public boolean permitted(){return use;}public boolean player(){return player;}public void start(StreamSpeed s){starts++;speed=s;}public void stop(){stops++;}public String status(){return "streams=off";}public void reply(String s){reply=s;}}
    @Test void commandChecksExistingPermissionsConfigAndFastRestriction(){var thread=new ThreadGuard();var c=new StreamsCommands(thread,M8Config.from(Map.of("enabled",true,"heavyAllowed",false)));var p=new Probe();p.use=false;c.execute(p,new String[0]);assertEquals(0,p.starts);p.use=true;p.player=false;c.execute(p,new String[0]);assertEquals(0,p.starts);p.player=true;c.execute(p,new String[]{"fast"});assertEquals(0,p.starts);c.execute(p,new String[0]);assertEquals(StreamSpeed.NORMAL,p.speed);c.execute(p,new String[]{"slow"});assertEquals(StreamSpeed.SLOW,p.speed);c.execute(p,new String[]{"stop"});assertEquals(1,p.stops);c.execute(p,new String[]{"status"});assertEquals("streams=off",p.reply);c.execute(p,new String[]{"normal","extra"});assertEquals(2,p.starts);new StreamsCommands(thread,M8Config.from(Map.of())).execute(p,new String[0]);assertEquals(2,p.starts);assertEquals(List.of("normal"),c.suggest(new String[]{"n"}));}
    @Test void independentEmitterCallCapCannotSendHalfAPair(){var f=new StreamsFixture();f.normal();f.run();var d=f.draft(A);var c=new RequestContext(d.requestId(),d.ownerViewerId(),d.worldId(),0,64,0,d.directions());long[] calls={0};ParticleSink sink=new ParticleSink(){public void send(long a,int b,StyleKey s,double x,double y,double z){fail("positional fallback");}public void sendDirectional(long a,int b,StyleKey s,double x,double y,double z,DirectionalEmission motion){calls[0]++;}};var report=new DefaultPlanEmitter().emit(f.plan,Map.of(d.requestId(),c),f.health,(a,b)->Optional.empty(),(w,x,y,z)->Optional.empty(),sink,new EmissionLimits(1,1));assertEquals(0,calls[0]);assertEquals(2,report.placementsInSkippedRecipients());assertEquals(1,report.skippedRecipients().get(SkipReason.EMISSION_LIMIT));}
    @Test void nonOpposingOrMismatchedSpeedPayloadsFailClosedBeforeAnySend(){for(boolean speedMismatch:List.of(false,true)){var f=new StreamsFixture();f.normal();f.run();var d=f.draft(A);var motions=Map.of(DirectionalEmission.A,new DirectionalEmission(Vec3.Y,.15),DirectionalEmission.B,new DirectionalEmission(speedMismatch?Vec3.Y.mul(-1):Vec3.Y,speedMismatch?.10:.15));var c=new RequestContext(d.requestId(),d.ownerViewerId(),d.worldId(),0,64,0,motions);var report=new DefaultPlanEmitter().emit(f.plan,Map.of(d.requestId(),c),f.health,(a,b)->Optional.empty(),(w,x,y,z)->Optional.empty(),(a,b,s,x,y,z)->fail("invalid pair sent"),new EmissionLimits(10,10));assertEquals(0,report.attemptedCalls());assertEquals(2,report.placementsInSkippedDeliveries());}}
    @Test void duplicateDirectionalStylesAreRejectedWithoutThrowingFromTheEmitter(){var point=Shape.point(Vec3.ZERO);var timing=workshop.vfx.math.time.Timing.once(200);var scene=EffectScene.of(workshop.vfx.math.time.TimeDomain.GAME,200,List.of(new Layer("a",timing,Visibility.ACTIVE_ONLY,Reveal.ALL,Motion.IDENTITY,point,DirectionalEmission.A),new Layer("b",timing,Visibility.ACTIVE_ONLY,Reveal.ALL,Motion.IDENTITY,point,DirectionalEmission.A)),new SceneLimits(2,2));var frame=scene.evaluate(Pose.IDENTITY,workshop.vfx.math.time.Playback.start(workshop.vfx.math.time.TimePoint.gameTick(0)),workshop.vfx.math.time.TimePoint.gameTick(0));assertFalse(DirectionalEmission.validPair(frame,Map.of(DirectionalEmission.A,new DirectionalEmission(Vec3.Y,.15),DirectionalEmission.B,new DirectionalEmission(Vec3.Y.mul(-1),.15))));}
    @Test void paperUsesCountZeroDirectionAndSpeedOnlyForStreamsAndKeepsHistoricalCall() throws Exception{String text=Files.readString(Path.of(System.getProperty("adapter.root",".")).resolve("src/main/java/workshop/vfx/paper/bukkit/VfxDemoPlugin.java"));assertTrue(text.contains("player.spawnParticle(Particle.END_ROD,x,y,z,0,direction.x(),direction.y(),direction.z(),motion.speed(),null,false)"));assertTrue(text.contains("player.spawnParticle(resolved.particle(),x,y,z,0,0.0,0.0,0.0,0.0,resolved.data(),false)"));assertTrue(text.contains("registerCommand(\"vfxstreams\""));assertFalse(text.contains("world.spawnParticle"));assertFalse(text.contains("runTaskAsynchronously"));}
}
